// Filename: Wasp2Sprite.js
// Kitty Vs Everything — v1.0.0
// Sprite pipeline for the Wasp2 enemy: the black wireframe wasp silhouette
// from `../.assets/Wasp 1 Pixel Art.png` (882x500, black on white, no alpha).
//
// The PNG is embedded below as base64 (144,255 bytes, generated from the
// file on 2026-09-25) so the sprite works in BOTH the dev server (native
// ES modules) and the single-file standalone build (game-standalone.html
// runs from a double-click — no server, no .assets folder next to it).
//
// Pipeline (runs once, at import time — long before the first Wasp2 spawns):
//   1. Strip the black frame: the source has a rectangular border drawn around
//      the wasp. Flood-fill non-white pixels from the image edges and drop them
//      (the wasp is centered and disconnected from the border).
//   2. Key the white background to transparent: alpha = 255 - luminance,
//      RGB forced to black. Pure black stays fully opaque, pure white
//      becomes fully transparent, anti-aliased edges become soft alpha.
//   3. Downscale 882x500 -> 256x145 (bilinear, averages thin outline lines).
//   4. One-pixel alpha dilation so the 1-px wireframe lines survive the
//      in-game downscale (a mob Wasp2 is drawn at ~96 px wide).
export const VERSION = 'v1.0.0';

const PNG_BASE64 = '';

const SPRITE_W = 256;
const SPRITE_H = 145; // 882:500 aspect ratio

let spriteCanvas = null;
let loadPromise = null;

function buildSprite(img) {
  const W = img.naturalWidth;
  const H = img.naturalHeight;

  // 1) Full-res keying: black silhouette on transparent background
  const full = document.createElement('canvas');
  full.width = W;
  full.height = H;
  const fctx = full.getContext('2d', { willReadFrequently: true });
  fctx.drawImage(img, 0, 0);
  const id = fctx.getImageData(0, 0, W, H);
  const px = id.data;

  // 1a) Strip the black frame. The source PNG has a rectangular border drawn
  //     AROUND the wasp (it touches all four edges). Flood-fill every non-white
  //     pixel reachable from the image edges — that traces the frame. The wasp
  //     is centered and disconnected from the border, so it is left untouched.
  const N = W * H;
  const frame = new Uint8Array(N);
  const stack = [];
  const pushFrame = (x, y) => {
    const i = (y * W + x) * 4;
    const p = i >> 2;
    const lum = (px[i] + px[i + 1] + px[i + 2]) / 3;
    if (lum < 240 && !frame[p]) { frame[p] = 1; stack.push(p); }
  };
  for (let x = 0; x < W; x++) { pushFrame(x, 0); pushFrame(x, H - 1); }
  for (let y = 0; y < H; y++) { pushFrame(0, y); pushFrame(W - 1, y); }
  let sp = 0;
  while (sp < stack.length) {
    const p = stack[sp++];
    const cx = p % W;
    const cy = (p / W) | 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = cx + dx, ny = cy + dy;
        if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
        pushFrame(nx, ny);
      }
    }
  }

  // 1b) Keying: frame pixels -> fully transparent; wasp pixels -> black
  //     silhouette (black -> opaque, white -> transparent).
  for (let i = 0; i < px.length; i += 4) {
    if (frame[i >> 2]) { px[i + 3] = 0; continue; }
    const lum = (px[i] + px[i + 1] + px[i + 2]) / 3;
    px[i] = 0;
    px[i + 1] = 0;
    px[i + 2] = 0;
    px[i + 3] = 255 - lum; // black -> opaque, white -> transparent
  }
  fctx.putImageData(id, 0, 0);

  // 2) Bilinear downscale to the game sprite size
  const out = document.createElement('canvas');
  out.width = SPRITE_W;
  out.height = SPRITE_H;
  const octx = out.getContext('2d', { willReadFrequently: true });
  octx.imageSmoothingEnabled = true;
  octx.imageSmoothingQuality = 'high';
  octx.drawImage(full, 0, 0, SPRITE_W, SPRITE_H);

  // 3) One-pixel alpha dilation — keeps the thin wireframe lines visible
  //    when the sprite is downscaled again during gameplay.
  const od = octx.getImageData(0, 0, SPRITE_W, SPRITE_H);
  const a = od.data;
  const src = a.slice();
  for (let y = 0; y < SPRITE_H; y++) {
    for (let x = 0; x < SPRITE_W; x++) {
      const i = (y * SPRITE_W + x) * 4 + 3; // alpha channel
      let m = src[i];
      if (x > 0) m = Math.max(m, src[i - 4]);
      if (x < SPRITE_W - 1) m = Math.max(m, src[i + 4]);
      if (y > 0) m = Math.max(m, src[i - SPRITE_W * 4]);
      if (y < SPRITE_H - 1) m = Math.max(m, src[i + SPRITE_W * 4]);
      a[i] = m;
    }
  }
  octx.putImageData(od, 0, 0);
  return out;
}

/** @returns {HTMLCanvasElement|null} Processed sprite, or null before ready. */
export function getWasp2Sprite() {
  return spriteCanvas;
}

/** @returns {boolean} True once the sprite pipeline has finished. */
export function isWasp2SpriteReady() {
  return spriteCanvas !== null;
}

/**
 * Kick off (or join) the sprite pipeline.
 * @returns {Promise<void>} Resolves when the sprite is ready.
 */
export function loadWasp2Sprite() {
  if (!loadPromise) {
    loadPromise = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        try {
          spriteCanvas = buildSprite(img);
          resolve();
        } catch (err) {
          loadPromise = null; // allow a retry
          reject(err);
        }
      };
      img.onerror = () => {
        loadPromise = null;
        reject(new Error('Wasp2 sprite: failed to decode embedded PNG'));
      };
      img.src = 'data:image/png;base64,' + PNG_BASE64;
    });
  }
  return loadPromise;
}

// Start at import time: Wasp2 first spawns on wave 2, so the sprite is long
// ready by then. Failures are non-fatal — Wasp2Enemy falls back to a plain
// dark circle until (if) the pipeline succeeds.
loadWasp2Sprite().catch(() => {});
